<?php
declare(strict_types=1);

function manage_xlsx_escape(mixed $value): string {
    return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
}

function manage_xlsx_xml(string $xml): DOMXPath {
    $document=new DOMDocument();$previous=libxml_use_internal_errors(true);
    if(!$document->loadXML($xml,LIBXML_NONET|LIBXML_NOBLANKS)){libxml_clear_errors();libxml_use_internal_errors($previous);throw new RuntimeException('The Excel workbook contains invalid XML.');}
    libxml_clear_errors();libxml_use_internal_errors($previous);$xpath=new DOMXPath($document);$xpath->registerNamespace('x','http://schemas.openxmlformats.org/spreadsheetml/2006/main');$xpath->registerNamespace('r','http://schemas.openxmlformats.org/officeDocument/2006/relationships');$xpath->registerNamespace('p','http://schemas.openxmlformats.org/package/2006/relationships');return $xpath;
}

function manage_xlsx_entry(ZipArchive $zip,string $name,int $maximum=12000000): string {
    $stat=$zip->statName($name);if(!$stat||($stat['size']??0)>$maximum)throw new RuntimeException('The Excel worksheet is too large to preview.');$contents=$zip->getFromName($name);if($contents===false)throw new RuntimeException('A required Excel worksheet part is missing.');return $contents;
}

function manage_xlsx_column_index(string $reference): int {
    if(!preg_match('/^([A-Z]+)/i',$reference,$match))return 0;$index=0;foreach(str_split(strtoupper($match[1])) as $letter)$index=$index*26+(ord($letter)-64);return max(0,$index-1);
}

function manage_xlsx_indexed_color(int $index): string {
    $colors=[0=>'#000000',1=>'#FFFFFF',2=>'#FF0000',3=>'#00FF00',4=>'#0000FF',5=>'#FFFF00',6=>'#FF00FF',7=>'#00FFFF',8=>'#000000',9=>'#FFFFFF',10=>'#FF0000',11=>'#00FF00',12=>'#0000FF',13=>'#FFFF00',14=>'#FF00FF',15=>'#00FFFF',16=>'#800000',17=>'#008000',18=>'#000080',19=>'#808000',20=>'#800080',21=>'#008080',22=>'#C0C0C0',23=>'#808080',40=>'#00CCFF',41=>'#CCFFFF',42=>'#CCFFCC',43=>'#FFFF99',44=>'#99CCFF',45=>'#FF99CC',46=>'#CC99FF',47=>'#FFCC99'];return $colors[$index]??'#FFFFFF';
}

function manage_xlsx_color(?DOMElement $element): string {
    if(!$element)return'';$rgb=strtoupper($element->getAttribute('rgb'));if(preg_match('/^[A-F0-9]{8}$/',$rgb))return'#'.substr($rgb,2);if(preg_match('/^[A-F0-9]{6}$/',$rgb))return'#'.$rgb;if($element->hasAttribute('indexed'))return manage_xlsx_indexed_color((int)$element->getAttribute('indexed'));return'';
}

function manage_xlsx_decimal_places(string $format): int {
    $plain=preg_replace('/"[^"]*"|\\./','',$format)??$format;$dot=strpos($plain,'.');if($dot===false)return 0;$tail=substr($plain,$dot+1);preg_match('/^[0#]+/',$tail,$match);return strlen($match[0]??'');
}

function manage_xlsx_format_number(float $value,int $formatId,string $format): string {
    $dateFormat=in_array($formatId,range(14,22),true)||(bool)preg_match('/(?:^|[^\[])[dmy]{1,4}[\-\/ ]/i',$format);
    if($dateFormat){$seconds=(int)round(($value-25569)*86400);$date=(new DateTimeImmutable('@'.$seconds))->setTimezone(new DateTimeZone('UTC'));if(str_contains(strtolower($format),'mmm'))return $date->format(str_contains(strtolower($format),'yyyy')?'d-M-Y':'d-M-y');return $date->format('m/d/Y');}
    if(str_contains($format,'%')||in_array($formatId,[9,10],true))return number_format($value*100,manage_xlsx_decimal_places($format),'.',',').'%';
    $decimals=match($formatId){2,4=>2,1,3=>0,default=>manage_xlsx_decimal_places($format)};$useThousands=in_array($formatId,[3,4],true)||str_contains($format,',');$currency=(bool)preg_match('/[$£€¥]/u',$format,$currencyMatch);if($formatId===0&&$format==='')return abs($value-round($value))<0.0000001?(string)(int)round($value):rtrim(rtrim(number_format($value,8,'.',''), '0'),'.');$number=number_format($value,$decimals,'.',$useThousands?',':'');return($currency?$currencyMatch[0]:'').$number;
