        $relationsXml=manage_xlsx_xml(manage_xlsx_entry($zip,'xl/_rels/workbook.xml.rels'));
        $relations=[];foreach($relationsXml->query('//p:Relationship')?:[] as $relation)if($relation instanceof DOMElement)$relations[$relation->getAttribute('Id')]=$relation->getAttribute('Target');
        $sheets=[];foreach($workbookXml->query('//x:sheets/x:sheet')?:[] as $sheet){if(!$sheet instanceof DOMElement)continue;$relationshipId=$sheet->getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');$target=$relations[$relationshipId]??'';if($target==='')continue;$target=ltrim(str_replace('../','',$target),'/');$sheets[]=['name'=>$sheet->getAttribute('name')?:'Sheet '.(count($sheets)+1),'path'=>str_starts_with($target,'xl/')?$target:'xl/'.$target];}
        if(!$sheets)throw new RuntimeException('The Excel workbook does not contain a worksheet.');$selectedSheet=max(0,min($selectedSheet,count($sheets)-1));$sheetInfo=$sheets[$selectedSheet];
        $sharedStrings=[];if($zip->locateName('xl/sharedStrings.xml')!==false){$sharedXml=manage_xlsx_xml(manage_xlsx_entry($zip,'xl/sharedStrings.xml'));foreach($sharedXml->query('//x:si')?:[] as $item){$parts=[];foreach((new DOMXPath($item->ownerDocument))->query('.//*[local-name()="t"]',$item)?:[] as $text)$parts[]=$text->textContent;$sharedStrings[]=implode('',$parts);}}
        $formats=[0=>'',1=>'0',2=>'0.00',3=>'#,##0',4=>'#,##0.00',9=>'0%',10=>'0.00%',14=>'mm-dd-yy'];$fonts=[];$fills=[];$cellStyles=[];$stylesXml=manage_xlsx_xml(manage_xlsx_entry($zip,'xl/styles.xml'));
        foreach($stylesXml->query('//x:numFmts/x:numFmt')?:[] as $format)if($format instanceof DOMElement)$formats[(int)$format->getAttribute('numFmtId')]=$format->getAttribute('formatCode');
        foreach($stylesXml->query('//x:fonts/x:font')?:[] as $font){$fontXPath=new DOMXPath($font->ownerDocument);$fontXPath->registerNamespace('x','http://schemas.openxmlformats.org/spreadsheetml/2006/main');$size=$fontXPath->query('./x:sz',$font)?->item(0);$color=$fontXPath->query('./x:color',$font)?->item(0);$fonts[]=['bold'=>$fontXPath->query('./x:b',$font)?->length>0,'italic'=>$fontXPath->query('./x:i',$font)?->length>0,'size'=>$size instanceof DOMElement?(float)$size->getAttribute('val'):11,'color'=>$color instanceof DOMElement?manage_xlsx_color($color):''];}
        foreach($stylesXml->query('//x:fills/x:fill')?:[] as $fill){$fillXPath=new DOMXPath($fill->ownerDocument);$fillXPath->registerNamespace('x','http://schemas.openxmlformats.org/spreadsheetml/2006/main');$color=$fillXPath->query('./x:patternFill/x:fgColor',$fill)?->item(0);$fills[]=$color instanceof DOMElement?manage_xlsx_color($color):'';}
        foreach($stylesXml->query('//x:cellXfs/x:xf')?:[] as $style){if(!$style instanceof DOMElement)continue;$alignment=null;foreach($style->childNodes as $child)if($child instanceof DOMElement&&$child->localName==='alignment'){$alignment=$child;break;}$cellStyles[]=['font'=>(int)$style->getAttribute('fontId'),'fill'=>(int)$style->getAttribute('fillId'),'border'=>(int)$style->getAttribute('borderId'),'format'=>(int)$style->getAttribute('numFmtId'),'align'=>$alignment?preg_replace('/[^a-z]/','',strtolower($alignment->getAttribute('horizontal'))):'','wrap'=>$alignment&&$alignment->getAttribute('wrapText')==='1'];}
        $sheetXml=manage_xlsx_xml(manage_xlsx_entry($zip,$sheetInfo['path']));$dimension=$sheetXml->query('//x:dimension')?->item(0);$maximumRow=1;$maximumColumn=1;if($dimension instanceof DOMElement&&preg_match('/([A-Z]+)(\d+)$/i',$dimension->getAttribute('ref'),$dimensionMatch)){$maximumColumn=manage_xlsx_column_index($dimensionMatch[1])+1;$maximumRow=(int)$dimensionMatch[2];}$truncated=$maximumRow>500||$maximumColumn>100;$maximumRow=min(500,max(1,$maximumRow));$maximumColumn=min(100,max(1,$maximumColumn));
        $columnWidths=array_fill(0,$maximumColumn,88);foreach($sheetXml->query('//x:cols/x:col')?:[] as $column){if(!$column instanceof DOMElement)continue;$start=max(1,(int)$column->getAttribute('min'));$end=min($maximumColumn,(int)$column->getAttribute('max'));$width=min(260,max(32,(float)$column->getAttribute('width')*7+8));for($index=$start-1;$index<$end;$index++)$columnWidths[$index]=(int)round($width);}
        $rowHeights=[];foreach($sheetXml->query('//x:sheetData/x:row')?:[] as $row)if($row instanceof DOMElement&&$row->hasAttribute('ht'))$rowHeights[(int)$row->getAttribute('r')]=min(100,max(20,(int)round((float)$row->getAttribute('ht')*1.34)));
        $cells=[];foreach($sheetXml->query('//x:sheetData/x:row/x:c')?:[] as $cell){if(!$cell instanceof DOMElement)continue;$reference=$cell->getAttribute('r');if(!preg_match('/^[A-Z]+(\d+)$/i',$reference,$referenceMatch))continue;$rowIndex=(int)$referenceMatch[1];$columnIndex=manage_xlsx_column_index($reference);if($rowIndex<1||$rowIndex>$maximumRow||$columnIndex>=$maximumColumn)continue;$type=$cell->getAttribute('t');$styleIndex=(int)$cell->getAttribute('s');$valueNode=null;$inlineNode=null;foreach($cell->childNodes as $child)if($child instanceof DOMElement){if($child->localName==='v')$valueNode=$child;elseif($child->localName==='is')$inlineNode=$child;}$raw=$valueNode?->textContent??'';$style=$cellStyles[$styleIndex]??['font'=>0,'fill'=>0,'border'=>0,'format'=>0,'align'=>'','wrap'=>false];if($type==='s')$value=$sharedStrings[(int)$raw]??'';elseif($type==='inlineStr')$value=$inlineNode?->textContent??'';elseif($type==='b')$value=$raw==='1'?'TRUE':'FALSE';elseif($type==='e')$value=$raw;elseif($raw!==''&&is_numeric($raw))$value=manage_xlsx_format_number((float)$raw,(int)$style['format'],$formats[(int)$style['format']]??'');else $value=$raw;$cells[$rowIndex][$columnIndex]=['value'=>$value,'numeric'=>$type==='n'||($type===''&&is_numeric($raw)),'style'=>$style];}
        $mergeStarts=[];$mergeCovered=[];foreach($sheetXml->query('//x:mergeCells/x:mergeCell')?:[] as $merge){if(!$merge instanceof DOMElement||!preg_match('/^([A-Z]+)(\d+):([A-Z]+)(\d+)$/i',$merge->getAttribute('ref'),$match))continue;$startColumn=manage_xlsx_column_index($match[1]);$startRow=(int)$match[2];$endColumn=min($maximumColumn-1,manage_xlsx_column_index($match[3]));$endRow=min($maximumRow,(int)$match[4]);if($startRow>$maximumRow||$startColumn>=$maximumColumn)continue;$mergeStarts[$startRow][$startColumn]=['rowspan'=>$endRow-$startRow+1,'colspan'=>$endColumn-$startColumn+1];for($row=$startRow;$row<=$endRow;$row++)for($column=$startColumn;$column<=$endColumn;$column++)if($row!==$startRow||$column!==$startColumn)$mergeCovered[$row][$column]=true;}
        $query=$baseQuery;$html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.manage_xlsx_escape($filename).'</title><style>*{box-sizing:border-box}html,body{height:100%;margin:0;background:#eef2f5;color:#1c2e3f;font-family:Arial,sans-serif}.xlsx-shell{display:grid;grid-template-rows:auto minmax(0,1fr);height:100%}.xlsx-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:9px 12px;border-bottom:1px solid #cbd7e0;background:#fff}.xlsx-title{min-width:0;overflow:hidden;font-size:12px;font-weight:800;text-overflow:ellipsis;white-space:nowrap}.xlsx-tabs{display:flex;gap:5px;overflow-x:auto}.xlsx-tabs a{padding:6px 10px;border:1px solid #c8d5df;border-radius:7px;background:#f5f8fa;color:#36566f;font-size:10px;font-weight:800;text-decoration:none;white-space:nowrap}.xlsx-tabs a.active{border-color:#316f9d;background:#316f9d;color:#fff}.xlsx-scroll{overflow:auto;padding:10px}.xlsx-sheet{border-collapse:collapse;table-layout:fixed;background:#fff;box-shadow:0 4px 18px rgba(17,43,66,.1)}.xlsx-sheet td{height:22px;padding:2px 5px;overflow:hidden;border:1px solid #dfe5ea;color:#202b34;font-size:11px;line-height:1.25;text-overflow:ellipsis;white-space:nowrap}.xlsx-note{padding:7px 10px;background:#fff5d8;color:#72540e;font-size:11px}</style></head><body><div class="xlsx-shell"><div class="xlsx-toolbar"><span class="xlsx-title">'.manage_xlsx_escape($filename).'</span><nav class="xlsx-tabs" aria-label="Workbook sheets">';
        foreach($sheets as $sheetIndex=>$sheet){$query['sheet']=$sheetIndex;$html.='<a class="'.($sheetIndex===$selectedSheet?'active':'').'" href="?'.manage_xlsx_escape(http_build_query($query)).'">'.manage_xlsx_escape($sheet['name']).'</a>';}$html.='</nav></div><div class="xlsx-scroll">';if($truncated)$html.='<div class="xlsx-note">Preview limited to the first 500 rows and 100 columns.</div>';$html.='<table class="xlsx-sheet" aria-label="'.manage_xlsx_escape($sheetInfo['name']).'"><colgroup>';foreach($columnWidths as $width)$html.='<col style="width:'.$width.'px">';$html.='</colgroup><tbody>';
